SELECT COUNT(*) AS Number_of_Claims
FROM Claim
JOIN Policy ON Claim.Insurable_Object_Identifier = Policy.Insurable_Object_Identifier;

```sql
SELECT COUNT(DISTINCT Claim.Company_Claim_Number) FROM Claim JOIN Policy ON Claim.Insurable_Object_Identifier = Policy.Policy_Identifier;
```
